export function scrollToBottom() {
    const list = document.querySelector('.message-list');
    if (list) {
        list.scrollTop = list.scrollHeight;
    }
}

let _scrollHandler = null;

export function registerScrollHandler(dotNetRef) {
    const list = document.querySelector('.message-list');
    if (!list) return;

    if (_scrollHandler) {
        list.removeEventListener('scroll', _scrollHandler);
    }

    _scrollHandler = () => {
        if (list.scrollTop === 0) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    };

    list.addEventListener('scroll', _scrollHandler);
}

export function dispose() {
    const list = document.querySelector('.message-list');
    if (list && _scrollHandler) {
        list.removeEventListener('scroll', _scrollHandler);
        _scrollHandler = null;
    }
}

