1. @page "/chat"
2. @layout ChatLayout
3. @using sv_3b56dfa00d1846ba9e2ce87bc1974666.Services
4. @using sv_3b56dfa00d1846ba9e2ce87bc1974666.Components.Layout
5. @rendermode InteractiveServer
6. @inject IChatService ChatService
7. @inject IJSRuntime JS
8. @implements IAsyncDisposable
9. 
10. <div class="chat-container">
11.     <div class="chat-sidebar">
12.         <ChannelSidebar Channels="_channels"
13.                         ActiveChannelId="_activeChannelId"
14.                         OnChannelSelected="SelectChannel" />
15.     </div>
16. 
17.     <div class="chat-main @(_threadOpen ? "" : "expanded")">
18.         @if (_activeChannel is not null)
19.         {
20.             <MessageArea ChannelName="@_activeChannel.Name"
21.                          ChannelDescription="@_activeChannel.Description"
22.                          Messages="_messages"
23.                          ThreadReplyCounts="_threadReplyCounts"
24.                          IsLoadingMore="_loadingMore"
25.                          OnSendMessage="SendMessage"
26.                          OnReplyClicked="OpenThread"
27.                          OnThreadClicked="OpenThread"
28.                          OnReactionAdded="AddReaction" />
29.         }
30.         else
31.         {
32.             <div class="empty-state">
33.                 <p>Select a channel to start chatting</p>
34.             </div>
35.         }
36.     </div>
37. 
38.     @if (_threadOpen && _threadRootMessage is not null)
39.     {
40.         <div class="chat-thread">
41.             <ThreadPanel RootMessage="_threadRootMessage"
42.                          Replies="_threadReplies"
43.                          OnClose="CloseThread"
44.                          OnSendReply="SendThreadReply"
45.                          OnReactionAdded="AddReaction" />
46.         </div>
47.     }
48. </div>
49. 
50. @code {
51.     private List<Channel> _channels = [];
52.     private List<Message> _messages = [];
53.     private Dictionary<int, int> _threadReplyCounts = [];
54.     private Channel? _activeChannel;
55.     private int _activeChannelId;
56.     private int _skip;
57.     private const int PageSize = 30;
58. 
59.     // Thread state
60.     private bool _threadOpen;
61.     private Message? _threadRootMessage;
62.     private List<Message> _threadReplies = [];
63.     private bool _loadingMore;
64. 
65.     private IJSObjectReference? _scrollModule;
66.     private DotNetObjectReference<ChatPage>? _dotNetRef;
67. 
68.     protected override async Task OnInitializedAsync()
69.     {
70.         _channels = await ChatService.GetChannelsAsync();
71.         if (_channels.Count > 0)
72.         {
73.             await SelectChannel(_channels[0].Id);
74.         }
75.     }
76. 
77.     protected override async Task OnAfterRenderAsync(bool firstRender)
78.     {
79.         if (firstRender)
80.         {
81.             _scrollModule = await JS.InvokeAsync<IJSObjectReference>(
82.                 "import", "./Components/Pages/Chat/ChatPage.razor.js");
83.             _dotNetRef = DotNetObjectReference.Create(this);
84.             await _scrollModule.InvokeVoidAsync("registerScrollHandler", _dotNetRef);
85.         }
86.     }
87. 
88.     private async Task SelectChannel(int channelId)
89.     {
90.         _activeChannelId = channelId;
91.         _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
92.         _skip = 0;
93.         _messages = await ChatService.GetMessagesAsync(channelId, _skip, PageSize);
94.         _skip = _messages.Count;
95. 
96.         BuildThreadReplyCounts();
97. 
98.         await ChatService.MarkChannelReadAsync(channelId);
99. 
100.         // Update unread count locally
101.         var idx = _channels.FindIndex(c => c.Id == channelId);
102.         if (idx >= 0)
103.         {
104.             _channels[idx] = _channels[idx] with { UnreadCount = 0 };
105.         }
106. 
107.         CloseThreadSync();
108.     }
109. 
110.     [JSInvokable]
111.     public async Task OnScrolledToTop()
112.     {
113.         if (_loadingMore || _activeChannel is null) return;
114.         _loadingMore = true;
115.         StateHasChanged();
116. 
117.         await LoadOlderMessages();
118. 
119.         _loadingMore = false;
120.         StateHasChanged();
121.     }
122. 
123.     private async Task LoadOlderMessages()
124.     {
125.         if (_activeChannel is null) return;
126. 
127.         var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _skip, PageSize);
128.         if (older.Count > 0)
129.         {
130.             _messages.InsertRange(0, older);
131.             _skip += older.Count;
132.             BuildThreadReplyCounts();
133.         }
134.     }
135. 
136.     private async Task SendMessage(string content)
137.     {
138.         if (_activeChannel is null) return;
139. 
140.         var msg = await ChatService.SendMessageAsync(_activeChannel.Id, content, null);
141.         _messages.Add(msg);
142.         _skip++;
143. 
144.         await ScrollToBottom();
145.     }
146. 
147.     private async Task OpenThread(int messageId)
148.     {
149.         _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
150.         if (_threadRootMessage is null) return;
151. 
152.         _threadReplies = await ChatService.GetThreadAsync(messageId);
153.         _threadOpen = true;
154.     }
155. 
156.     private void CloseThreadSync()
157.     {
158.         _threadOpen = false;
159.         _threadRootMessage = null;
160.         _threadReplies = [];
161.     }
162. 
163.     private Task CloseThread()
164.     {
165.         CloseThreadSync();
166.         return Task.CompletedTask;
167.     }
168. 
169.     private async Task SendThreadReply(string content)
170.     {
171.         if (_threadRootMessage is null || _activeChannel is null) return;
172. 
173.         var reply = await ChatService.SendMessageAsync(
174.             _activeChannel.Id, content, _threadRootMessage.Id);
175.         _threadReplies.Add(reply);
176. 
177.         // Update reply count
178.         _threadReplyCounts[_threadRootMessage.Id] =
179.             _threadReplyCounts.GetValueOrDefault(_threadRootMessage.Id) + 1;
180.     }
181. 
182.     private async Task AddReaction((int MessageId, string Emoji) args)
183.     {
184.         await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
185. 
186.         // Optimistic update in main message list
187.         UpdateReactionLocally(_messages, args.MessageId, args.Emoji);
188.         // Also update in thread replies if open
189.         UpdateReactionLocally(_threadReplies, args.MessageId, args.Emoji);
190.     }
191. 
192.     private static void UpdateReactionLocally(List<Message> list, int messageId, string emoji)
193.     {
194.         var idx = list.FindIndex(m => m.Id == messageId);
195.         if (idx < 0) return;
196. 
197.         var msg = list[idx];
198.         var reactions = msg.Reactions.ToList();
199.         var existing = reactions.FindIndex(r => r.Emoji == emoji);
200.         if (existing >= 0)
201.         {
202.             var r = reactions[existing];
203.             reactions[existing] = r with { Users = [..r.Users, "You"] };
204.         }
205.         else
206.         {
207.             reactions.Add(new Reaction(emoji, ["You"]));
208.         }
209. 
210.         list[idx] = msg with { Reactions = reactions };
211.     }
212. 
213.     private void BuildThreadReplyCounts()
214.     {
215.         _threadReplyCounts = _messages
216.             .Where(m => m.ReplyToId is not null)
217.             .GroupBy(m => m.ReplyToId!.Value)
218.             .ToDictionary(g => g.Key, g => g.Count());
219.     }
220. 
221.     private async Task ScrollToBottom()
222.     {
223.         if (_scrollModule is not null)
224.         {
225.             await _scrollModule.InvokeVoidAsync("scrollToBottom");
226.         }
227.     }
228. 
229.     public async ValueTask DisposeAsync()
230.     {
231.         if (_scrollModule is not null)
232.         {
233.             await _scrollModule.InvokeVoidAsync("dispose");
234.             await _scrollModule.DisposeAsync();
235.         }
236.         _dotNetRef?.Dispose();
237.     }
238. }
239.

